from target import top_products

def test_clear_top():
    assert top_products({"a": 5, "b": 9}, 1) == ["b"]

def test_all_names():
    assert top_products({"y": 1, "x": 1}, 2) == ["x", "y"]

def test_tie_by_name():
    assert top_products({"banana": 3, "apple": 3, "fig": 1}, 2) == [
        "apple", "banana"]
